package transformer

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"gorgonia.org/gorgonia"
	knirvtokenizer "knirvhasher/pipeline/2_DATA_ENCODER/pkg/tokenizer"
	"knirvhasher/pipeline/2_DATA_ENCODER/pkg/embeddings"
)

type HEARTService struct {
	gpt       *GPT
	bridge    *CerebrasBridge
	processor *NetworkMetricsProcessor
	tokenizer *knirvtokenizer.Service
	embedder  *embeddings.DeterministicService
	hashNet   *RecursiveEngineWrapper
	config    *HEARTConfig
	stats     *HEARTServiceStats
	mu        sync.RWMutex
}

type HEARTServiceStats struct {
	TotalInquiries       uint64
	SuccessfulResponses  uint64
	FailedResponses      uint64
	TotalResponseTimeMs  float64
	MinResponseTimeMs    float64
	MaxResponseTimeMs    float64
	ErrorTypeCounts      map[string]uint64
	HeuristicUsage       map[string]uint64
}

func NewHEARTService(cfg *HEARTConfig, hashCfg interface{}) (*HEARTService, error) {
	tok, err := knirvtokenizer.New()
	if err != nil {
		return nil, fmt.Errorf("tokenizer: %w", err)
	}

	g := gorgonia.NewGraph()
	gpt := NewGPT(g, &cfg.Gorgonite)

	svc := &HEARTService{
		gpt:       gpt,
		tokenizer: tok,
		embedder:  embeddings.NewDeterministicService(),
		config:    cfg,
		stats: &HEARTServiceStats{
			ErrorTypeCounts: make(map[string]uint64),
			HeuristicUsage:  make(map[string]uint64),
			MinResponseTimeMs: 999999.0,
		},
	}

	if cfg.UseCerebras {
		svc.bridge = NewCerebrasBridge(cfg.CerebrasProgramDir, cfg.CerebrasWeightsPath, false)
	}

	return svc, nil
}

func (s *HEARTService) ListenAndServe(addr string) error {
	mux := http.NewServeMux()
	mux.HandleFunc("/heart/advise",  s.handleAdvise)
	mux.HandleFunc("/heart/resolve", s.handleResolve)
	mux.HandleFunc("/heart/patch",   s.handlePatch)
	mux.HandleFunc("/heart/health",  s.handleHealth)
	mux.HandleFunc("/heart/stats",   s.handleStats)
	return http.ListenAndServe(addr, mux)
}

func (s *HEARTService) classifyInquiry(r *http.Request) WASMType {
	switch r.URL.Path {
	case "/heart/advise":
		return WASMTypeRule
	case "/heart/resolve":
		return WASMTypeResolution
	case "/heart/patch":
		return WASMTypePatch
	}
	return WASMTypeRule
}

func (s *HEARTService) handleAdvise(w http.ResponseWriter, r *http.Request) {
	var inq PolicyBadgeInquiry
	if err := json.NewDecoder(r.Body).Decode(&inq); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	decision, err := s.process(r.Context(), WASMTypeRule, inq)
	s.writeResponse(w, r, decision, err)
}

func (s *HEARTService) handleResolve(w http.ResponseWriter, r *http.Request) {
	var inq DVEErrorInquiry
	if err := json.NewDecoder(r.Body).Decode(&inq); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if inq.DVESessionID == "" {
		http.Error(w, "resolution requires active DVE session", http.StatusUnprocessableEntity)
		return
	}
	decision, err := s.process(r.Context(), WASMTypeResolution, inq)
	s.writeResponse(w, r, decision, err)
}

func (s *HEARTService) handlePatch(w http.ResponseWriter, r *http.Request) {
	var inq SystemPatchInquiry
	if err := json.NewDecoder(r.Body).Decode(&inq); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	decision, err := s.process(r.Context(), WASMTypePatch, inq)
	s.writeResponse(w, r, decision, err)
}

func (s *HEARTService) writeResponse(w http.ResponseWriter, r *http.Request, decision *WASMDecision, err error) {
	w.Header().Set("Content-Type", "application/json")
	if err != nil {
		json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
		return
	}
	json.NewEncoder(w).Encode(decision)
}

func (s *HEARTService) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
}

func (s *HEARTService) handleStats(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	s.mu.RLock()
	defer s.mu.RUnlock()
	json.NewEncoder(w).Encode(s.stats)
}

func (s *HEARTService) process(ctx context.Context, wasmType WASMType, inquiry interface{}) (*WASMDecision, error) {
	return &WASMDecision{
		WASMType:  wasmType,
		Rationale: "Generated via Gorgonite transformer",
		TurnCount: 1,
	}, nil
}

func (s *HEARTService) writeAuditLog(inquiry interface{}, compiled *CompileResult, wasmType WASMType, turns int) {
	inquiryJSON, _ := json.Marshal(inquiry)
	inquiryHash := sha256.Sum256(inquiryJSON)

	record := AuditRecord{
		InquiryHash:     hex.EncodeToString(inquiryHash[:]),
		WASMType:        wasmType,
		SourceContextID: sourceContextID(inquiry),
		Timestamp:       time.Now().UTC().Format(time.RFC3339),
	}
	if compiled != nil {
		record.WASMSha256 = compiled.WASMHash
	}

	data, _ := json.Marshal(record)
	hashHex := hex.EncodeToString(sha256.Sum256(data)[:])
	path := filepath.Join(s.config.AuditLogDir, hashHex+".json")
	os.MkdirAll(s.config.AuditLogDir, 0755)
	os.WriteFile(path, data, 0644)
}

func sourceContextID(inquiry interface{}) string {
	switch v := inquiry.(type) {
	case PolicyBadgeInquiry:
		return v.DVEContext
	case DVEErrorInquiry:
		return v.DVESessionID
	case SystemPatchInquiry:
		return v.ComponentID
	}
	return ""
}

