+	if hsi.index >= len(hsi.sources) {
+		return ""
+	}
+	source := hsi.sources[hsi.index]
+	hsi.index++
+	return source
+}
+
+func (hsi *HashSourceIngestion) HasNext() bool {
+	return hsi.index < len(hsi.sources)
+}
+
