package transformer

import (
	"context"
	"fmt"

	"github.com/tetratelabs/wazero"
	"github.com/tetratelabs/wazero/api"
	"github.com/tetratelabs/wazero/imports/wazergo"
)

type WazeroGate struct {
	runtime     wazero.Runtime
	module      api.Module
	compiled    wazero.CompiledModule
	execResults map[string]interface{}
}

func NewWazeroGate() *WazeroGate {
	return &WazeroGate{
		execResults: make(map[string]interface{}),
	}
}

func (wg *WazeroGate) Compile(source string) error {
	ctx := context.Background()

	compilerConfig := wazero.NewCompilerConfig()
	runtime := wazero.NewRuntimeWithConfig(ctx, compilerConfig)

	wazergo.MustInstantiate(ctx, runtime)

	compiled, err := runtime.CompileModule(ctx, source)
	if err != nil {
		return fmt.Errorf("failed to compile WASM: %w", err)
	}

	wg.runtime = runtime
	wg.compiled = compiled
	return nil
}

func (wg *WazeroGate) CompileAndRun(source string, args ...string) (map[string]interface{}, error) {
	if err := wg.Compile(source); err != nil {
		return nil, err
	}
	return wg.Run(args...)
}

func (wg *WazeroGate) Run(args ...string) (map[string]interface{}, error) {
	ctx := context.Background()

	if wg.compiled == nil {
		return nil, fmt.Errorf("no compiled module")
	}

	module, err := wg.runtime.InstantiateModule(ctx, wg.compiled)
	if err != nil {
		return nil, fmt.Errorf("failed to instantiate module: %w", err)
	}

	wg.module = module

	results := make(map[string]interface{})

	exports := module.(*wazero.ModuleInstance).Exports
	for name, fn := range exports {
		if v := module.ExportedFunctionDefinitions(); v != nil {
			if fnDef, ok := v[name]; ok {
				if len(fnDef.ParamTypes()) > 0 {
					switch name {
					case "GuardrailClass", "ErrorClass", "PatchScope":
						if results[name] = fn.Call(); results[name] != nil {
							results[name] = results[name]
						}
					}
				}
			}
		}
	}

	if err := module.Close(ctx); err != nil {
		return nil, fmt.Errorf("failed to close module: %w", err)
	}

	wg.execResults = results
	return results, nil
}

func (wg *WazeroGate) CallFunction(name string, params ...interface{}) (interface{}, error) {
	if wg.module == nil {
		return nil, fmt.Errorf("no module instantiated")
	}

	externalName := name
	fn := wg.module.ExportedFunctionDefinitions()[externalName]
	if fn == nil {
		return nil, fmt.Errorf("function %s not found", name)
	}

	ctx := context.Background()

	var paramsList []uint64
	for _, p := range params {
		switch v := p.(type) {
		case uint32:
			paramsList = append(paramsList, uint64(v))
		case uint64:
			paramsList = append(paramsList, v)
		case int:
			paramsList = append(paramsList, uint64(v))
		case float32:
			paramsList = append(paramsList, uint64(int32(v)))
		case float64:
			paramsList = append(paramsList, uint64(v))
		default:
			paramsList = append(paramsList, 0)
		}
	}

	if len(paramsList) > 0 {
		results, err := fn.Call(ctx, paramsList...)
		if err != nil {
			return nil, fmt.Errorf("function call failed: %w", err)
		}
		if len(results) > 0 {
			return results[0], nil
		}
	}

	return nil, nil
}

func (wg *WazeroGate) GetResult(key string) interface{} {
	return wg.execResults[key]
}

func (wg *WazeroGate) Close() error {
	if wg.module != nil {
		ctx := context.Background()
		if err := wg.module.Close(ctx); err != nil {
			return err
		}
	}
	if wg.runtime != nil {
		ctx := context.Background()
		return wg.runtime.Close(ctx)
	}
	return nil
}

func (wg *WazeroGate) Validate(source string) (bool, string) {
	err := wg.Compile(source)
	if err != nil {
		return false, err.Error()
	}

	results, err := wg.Run()
	if err != nil {
		return false, err.Error()
	}

	if len(results) > 0 {
		return true, ""
	}

	return false, "no exports found"
}

type WazeroPool struct {
	gates   []*WazeroGate
	size    int
	index  int
}

func NewWazeroPool(size int) *WazeroPool {
	return &WazeroPool{
		gates: make([]*WazeroGate, size),
		size:  size,
		index: 0,
	}
}

func (wp *WazeroPool) Acquire() *WazeroGate {
	if wp.gates[wp.index] == nil {
		wp.gates[wp.index] = NewWazeroGate()
	}

	gate := wp.gates[wp.index]
	wp.index = (wp.index + 1) % wp.size

	return gate
}

func (wp *WazeroPool) Release(gate *WazeroGate) {
	_ = gate.Close()
}

func (wp *WazeroPool) CloseAll() {
	for _, gate := range wp.gates {
		if gate != nil {
			_ = gate.Close()
		}
	}
}

